"""Explicit assistant review of vocabulary-gap and contrast examples."""
import json
from pathlib import Path
from classify import rows
ROOT=Path(__file__).resolve().parent
acq={r['document_key']:r for f in ['acquisition.jsonl','recovery.jsonl'] for r in rows(ROOT/f)}
out=[]
def add(key,fields,modalities,context,ops=(),withheld=(),role='analysis_or_teaching_document',batch='gap-expansion'):
 r=acq[key];cs=json.loads((ROOT/'content'/r['content_file']).read_text())['chunks']
 def ev(needle):
  c=next(c for c in cs if needle in c['text']);i=c['text'].index(needle)
  return {'locator':c['locator'],'snippet':c['text'][max(0,i-30):i+len(needle)+110].replace('\n',' ')}
 labels=[]
 for f,terms in [('scientific_field',fields),('modality',modalities)]:
  for term in terms:labels.append({'facet':f,'term':term,'status':'content_supported','evidence':[ev(context)],'rationale':'Explicit source objective or input, reviewed separately from repository scope.'})
 for term,target,needle,oprole in ops:
  labels.append({'facet':'operation','term':term,'status':'content_supported','role':oprole,'target':target,'evidence':[ev(needle)],'rationale':'Reviewed source implementation or explicitly supplied result; no execution claim.'})
 out.append({'document_key':key,'source_sha256':r['sha256'],'labels':labels,'review':'assistant_individual_source_review','source_role':role,'withheld_labels':list(withheld),'review_batch':batch,'reviewed_facet_states':{'scientific_field':'content_supported' if fields else 'not_applicable','modality':'content_supported' if modalities else 'insufficient_evidence','operation':'selected_operations_reviewed'},'independent_review':False,'executed':False})
